import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p33_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_i2h_tanh(torch::Tensor x, torch::Tensor hidden,
                              torch::Tensor weight, torch::Tensor bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_i2h_tanh", &fused_i2h_tanh, "Fused cat+i2h+tanh (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Tiled GEMM kernel that fuses cat(x, hidden) @ W.T + bias + tanh
// x:      (M, K_x)   where K_x = input_size
// hidden: (M, K_h)   where K_h = hidden_size
// weight: (N, K_x+K_h) row-major, same layout as nn.Linear.weight
// bias:   (N,)
// out:    (M, N)     where N = hidden_size

#define TILE_M 16
#define TILE_N 16
#define TILE_K 32

__global__ void fused_i2h_tanh_kernel(
    const float* __restrict__ x,
    const float* __restrict__ hidden,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int M, int K_x, int K_h, int N)
{
    // Each block computes a TILE_M x TILE_N output tile
    int row = blockIdx.y * TILE_M + threadIdx.y;  // batch dim
    int col = blockIdx.x * TILE_N + threadIdx.x;  // hidden_out dim

    __shared__ float sA[TILE_M][TILE_K + 1];  // +1 to avoid bank conflicts
    __shared__ float sB[TILE_K][TILE_N + 1];

    float acc = 0.0f;
    int K_total = K_x + K_h;

    for (int t = 0; t < (K_total + TILE_K - 1) / TILE_K; t++) {
        int k_base = t * TILE_K;

        // Load tile of "virtual concatenated" input into sA
        int k_a = k_base + threadIdx.x;  // col index in K dim for sA load
        if (row < M && k_a < K_total) {
            if (k_a < K_x) {
                sA[threadIdx.y][threadIdx.x] = x[row * K_x + k_a];
            } else {
                sA[threadIdx.y][threadIdx.x] = hidden[row * K_h + (k_a - K_x)];
            }
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of weight into sB
        // weight is (N, K_total), row-major
        // sB[k_local][n_local] = weight[col_for_sB][k_base + k_local]
        int k_b = k_base + threadIdx.y;  // row index in K dim for sB load
        int n_b = blockIdx.x * TILE_N + threadIdx.x;  // col in N
        if (n_b < N && k_b < K_total) {
            sB[threadIdx.y][threadIdx.x] = weight[n_b * K_total + k_b];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Accumulate
        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {
            acc += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        acc += bias[col];
        out[row * N + col] = tanhf(acc);
    }
}

torch::Tensor fused_i2h_tanh(torch::Tensor x, torch::Tensor hidden,
                              torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(hidden.is_cuda(), "hidden must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(hidden.scalar_type() == torch::kFloat32, "hidden must be float32");

    int M = x.size(0);
    int K_x = x.size(1);
    int K_h = hidden.size(1);
    int N = weight.size(0);  // hidden_size

    auto out = torch::empty({M, N}, x.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    fused_i2h_tanh_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        hidden.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        M, K_x, K_h, N
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initialize the Vanilla RNN model.

                :param input_size: The number of input features (int).
                :param hidden_size: The size of the hidden state (int).
                :param output_size: The number of output features (int).
                """
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size
        self.hidden = torch.randn((batch_size, hidden_size))
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)
        self.h2o = nn.Linear(hidden_size, output_size)
        self.tanh = nn.Tanh()
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor, initial_hidden=None) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Forward pass of the Vanilla RNN.

                :param x: Input tensor of shape (batch_size, input_size).
                :param hidden: Hidden state tensor of shape (batch_size, hidden_size).
                :return: Output tensor of shape (batch_size, output_size), and the new hidden state.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if initial_hidden is not None:
                    self.hidden.copy_(initial_hidden)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        self.hidden = self.hidden.to(x.device)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        if (x.is_cuda and x.dtype == torch.float32 and
                self.hidden.is_cuda and self.hidden.dtype == torch.float32):
            try:
                next_hidden = _stark_get_extension().fused_i2h_tanh(
                    x.contiguous(),
                    self.hidden.contiguous(),
                    self.i2h.weight.contiguous(),
                    self.i2h.bias.contiguous()
                )
            except Exception:
                combined = torch.cat((x, self.hidden), dim=1)
                next_hidden = self.tanh(self.i2h(combined))
        else:
            combined = torch.cat((x, self.hidden), dim=1)
            next_hidden = self.tanh(self.i2h(combined))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        self.hidden = next_hidden
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        output = self.h2o(self.hidden)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return output
        # <<<END_IMPROVE>>>

