CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_i2h_tanh(torch::Tensor x, torch::Tensor hidden,
                              torch::Tensor weight, torch::Tensor bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_i2h_tanh", &fused_i2h_tanh, "Fused split-input i2h + tanh (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Fused kernel: out[m, n] = tanh( sum_{k=0}^{Kx-1} x[m,k]*W[n,k]
//                                + sum_{k=0}^{Kh-1} h[m,k]*W[n,Kx+k]
//                                + bias[n] )
// x:      (M, Kx)       row-major
// hidden: (M, Kh)       row-major
// weight: (N, Kx+Kh)    row-major  (nn.Linear layout)
// bias:   (N,)
// out:    (M, N)

#define TILE_M 16
#define TILE_N 16
#define TILE_K 32

__global__ void fused_i2h_tanh_kernel(
    const float* __restrict__ x,
    const float* __restrict__ hidden,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int M, int Kx, int Kh, int N)
{
    int row = blockIdx.y * TILE_M + threadIdx.y;
    int col = blockIdx.x * TILE_N + threadIdx.x;

    __shared__ float sA[TILE_M][TILE_K + 1];
    __shared__ float sB[TILE_K][TILE_N + 1];

    float acc = 0.0f;
    int K_total = Kx + Kh;

    for (int t = 0; t < (K_total + TILE_K - 1) / TILE_K; t++) {
        int k_base = t * TILE_K;

        // Load tile of virtual-concatenated input into sA
        int k_a = k_base + threadIdx.x;
        if (row < M && k_a < K_total) {
            if (k_a < Kx) {
                sA[threadIdx.y][threadIdx.x] = x[row * Kx + k_a];
            } else {
                sA[threadIdx.y][threadIdx.x] = hidden[row * Kh + (k_a - Kx)];
            }
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of weight (transposed) into sB
        // weight[col, k] -> sB[k_local][col_local]
        int k_b = k_base + threadIdx.y;
        if (col < N && k_b < K_total) {
            sB[threadIdx.y][threadIdx.x] = weight[col * K_total + k_b];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {
            acc += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        out[row * N + col] = tanhf(acc + bias[col]);
    }
}

torch::Tensor fused_i2h_tanh(torch::Tensor x, torch::Tensor hidden,
                              torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(hidden.is_cuda(), "hidden must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(hidden.is_contiguous(), "hidden must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");

    int M  = x.size(0);
    int Kx = x.size(1);
    int Kh = hidden.size(1);
    int N  = weight.size(0);

    auto out = torch::empty({M, N}, x.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    fused_i2h_tanh_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        hidden.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        M, Kx, Kh, N
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initialize the Vanilla RNN model.

                :param input_size: The number of input features (int).
                :param hidden_size: The size of the hidden state (int).
                :param output_size: The number of output features (int).
                """
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size
        self.hidden = torch.randn((batch_size, hidden_size))
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)
        self.h2o = nn.Linear(hidden_size, output_size)
        self.tanh = nn.Tanh()
        # <<<END_IMPROVE>>>

