        and self.i2h.weight.dtype == torch.float32
        and self.i2h.bias.dtype == torch.float32
        and x.is_contiguous()
        and self.hidden.is_contiguous()
        and self.i2h.weight.is_contiguous()
        and self.i2h.bias.is_contiguous()
        and x.device == self.hidden.device
        and x.device == self.i2h.weight.device
        and x.device == self.i2h.bias.device
        and x.dim() == 2
        and self.hidden.dim() == 2
